import {parseAtlas,createAtlasPlayer,stableArtHash} from './unified-world-atlas.js';
import {fishSchoolMembers} from './unified-fish-layout.js';
import {animalGoal,createAnimalMotion} from './unified-world-motion.js';
import {configureAtlasFade,updateAtlasFade} from './unified-world-fade.js';
import {WORLD_ART} from './unified-world-art.js';
/** @typedef {{meta:Readonly<import('./unified-world-atlas.js').AtlasMetadata>,image:HTMLImageElement,pixels:Uint8ClampedArray,texture:Texture}} SpriteAsset */
/** @typedef {{key:string,motion:ReturnType<typeof createAnimalMotion>,offset:{x:number,z:number},entity:Readonly<import('./unified-world-model.js').WorldEntity>,group:import('three').Group,sprite:Sprite,asset:SpriteAsset|null,map:Texture|null,player:ReturnType<typeof createAtlasPlayer>|null,action:string,species:import('./unified-world-atlas.js').ArtSpecies,reactionUntil:number,reactionAction:string}} Actor */
/** Alpha-aware picking shared by raycast and Canvas. UV is normalized, bottom-origin.
 * @param {import('three').Object3D} object @param {{x:number,y:number}|undefined} uv */
export function spriteOpaque(object,uv){const data=object.userData.atlas;if(!data||!uv)return true;const m=data.asset.meta,at=(/** @type {{x:number,y:number,width:number,height:number}} */p)=>{const x=p.x+uv.x*p.width-.5,y=p.y+(1-uv.y)*p.height-.5,ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy,alpha=(/** @type {number} */px,/** @type {number} */py)=>data.asset.pixels[(Math.max(p.y,Math.min(p.y+p.height-1,py))*m.width+Math.max(p.x,Math.min(p.x+p.width-1,px)))*4+3];return(alpha(ix,iy)*(1-fx)+alpha(ix+1,iy)*fx)*(1-fy)+(alpha(ix,iy+1)*(1-fx)+alpha(ix+1,iy+1)*fx)*fy;};return(data.from?at(data.from)*(1-data.mix)+at(data.pose)*data.mix:at(data.pose))>=255*.08;}
/** Native activities only; pause breaks in an existing walk are cosmetic.
 * @param {Readonly<import('./unified-world-model.js').WorldEntity>} entity @param {number} now */
export function chickenPose(entity,now){if(entity.inside||entity.activity==='roost')return'rest';if(entity.activity==='drink')return'drink';if(entity.activity==='peck')return'eat';if(entity.activity==='walk')return Math.floor(now/1800+stableArtHash(entity.id)%7)%4===0?'idle':'walk';return'idle';}
/** @param {Readonly<import('./unified-world-model.js').WorldEntity>} entity */
export function goatPose(entity){const activity=entity.activity;if(activity==='chew'&&entity.forageAvailable===false)return'idle';return activity&&['idle','walk','browse','chew','rest','climb'].includes(activity)?activity:'idle';}
/** Native Cow selector already gates supply, comfort and lactation eligibility. @param {Readonly<import('./unified-world-model.js').WorldEntity>} entity */
export function cowPose(entity){return entity.activity==='eat'?'feed':entity.activity&&['idle','walk','drink','rest'].includes(entity.activity)?entity.activity:'idle';}
/** Native pending-feed/oxygen-factor/hour projection only. @param {Readonly<import('./unified-world-model.js').WorldEntity>} entity */
export function fishPose(entity){return entity.activity&&['swim','feed','surface','rest'].includes(entity.activity)?entity.activity:'rest';}
/** An accepted engine event is the sole source of the milking reaction. @param {import('./engine.js').DomainEvent} event */
export function milkedCow(event){return event.type==='cowMilked'&&typeof event.cowId==='string'&&typeof event.amount==='number'&&event.amount>0?'cow.animal.'+event.cowId:null;}
/** New native intake only; replacing/importing a save resets the baseline.
 * @param {Readonly<import('./unified-world-model.js').WorldEntity>} previous @param {Readonly<import('./unified-world-model.js').WorldEntity>} next @param {boolean} reset */
export function waterConsumed(previous,next,reset){return !reset&&next.kind==='goat'&&previous.kind===next.kind&&next.id===previous.id&&next.waterUsed!==undefined&&previous.waterUsed!==undefined&&next.waterUsed>previous.waterUsed;}
/** Cached local RGBA sprites. No RAF, game clock, reducer, save or game RNG.
 * @param {{changed:()=>void,low?:boolean}} options */
export function createWorldSprites(options){
 const cache=new Map(),assets=new Set(),actors=/** @type {Map<string,Actor>} */(new Map());let disposed=false,low=!!options.low,errors=0,lastTime=0,textureLimit=Infinity,resetPending=false;
 /** @type {readonly Readonly<import('./unified-world-model.js').WorldEntity>[]} */
 let worldEntities=[];
 /** @param {Actor} actor @returns {'high'|'low'} */
 const wanted=actor=>low||WORLD_ART.species[actor.species].framePixels*WORLD_ART.atlas.columns>textureLimit?'low':'high';
 /** @param {import('./unified-world-atlas.js').ArtSpecies} species @param {'high'|'low'} lod @returns {Promise<SpriteAsset>} */
 function load(species,lod){const key=species+':'+lod;if(cache.has(key))return cache.get(key);const promise=(async()=>{const base=new URL('./assets/world/',import.meta.url),module=await import(new URL(species+'.'+lod+'.js',base).href),meta=parseAtlas(module.default),image=new Image();if(meta.species!==species||meta.lod!==lod)throw Error('Atlas identity differs');image.src=new URL(meta.image,base).href;await image.decode();if(disposed)throw Error('Atlas disposed');if(image.width!==meta.width||image.height!==meta.height)throw Error('Atlas image dimensions differ');const canvas=document.createElement('canvas');canvas.width=meta.width;canvas.height=meta.height;const context=canvas.getContext('2d');if(!context)throw Error('Atlas alpha buffer unavailable');context.drawImage(image,0,0);const pixels=context.getImageData(0,0,meta.width,meta.height).data,texture=new Texture(image);texture.colorSpace=SRGBColorSpace;texture.minFilter=texture.magFilter=LinearFilter;texture.generateMipmaps=false;texture.needsUpdate=true;const asset={meta,image,pixels,texture};assets.add(asset);return asset;})();cache.set(key,promise);return promise;}
 /** @param {Actor} actor @param {SpriteAsset} asset */
 function install(actor,asset){if(disposed||actors.get(actor.key)!==actor)return;actor.map?.dispose();actor.asset=asset;actor.map=asset.texture.clone();actor.map.needsUpdate=true;actor.sprite.material.map=actor.map;actor.sprite.material.needsUpdate=true;actor.player=createAtlasPlayer(asset.meta,actor.entity.id);actor.player.setAction(actor.action,0);actor.sprite.center.set(asset.meta.pivot[0],1-asset.meta.pivot[1]);actor.sprite.scale.setScalar(asset.meta.worldUnits);attach(actor);}
 /** @param {Actor} actor */
 function request(actor){const lod=wanted(actor);load(actor.species,lod).then(asset=>{if(wanted(actor)!==lod)return;install(actor,asset);options.changed();}).catch(()=>{if(!disposed){errors++;options.changed();}});}
 /** A loaded sprite replaces primitives; stage scale is applied once to the sprite, not again by its parent. @param {Actor} actor */
 function attach(actor){if(!actor.group.userData.spriteBound){actor.group.clear();actor.group.scale.setScalar(1);actor.group.userData.spriteBound=true;}actor.group.add(actor.sprite);}
 /** @param {import('three').Group} group @param {Readonly<import('./unified-world-model.js').WorldEntity>} entity @param {string} key @param {{x:number,z:number}} offset */
 function bindOne(group,entity,key,offset){let actor=actors.get(key);if(actor){if(waterConsumed(actor.entity,entity,resetPending)){actor.reactionUntil=performance.now()+6500;actor.reactionAction='drink';}actor.entity=entity;actor.group=group;actor.offset=offset;if(resetPending)actor.motion.reset({x:entity.x+offset.x,z:entity.z+offset.z,y:entity.groundY||0});if(actor.asset)attach(actor);return;}const sprite=new Sprite(new SpriteMaterial({transparent:true,alphaTest:.08,depthWrite:false,toneMapped:false}));sprite.frustumCulled=false;configureAtlasFade(sprite);sprite.userData.entityId=entity.id;sprite.userData.kind=entity.kind+'Sprite';actor={key,motion:createAnimalMotion({x:entity.x+offset.x,z:entity.z+offset.z,y:entity.groundY||0}),offset,entity,group,sprite,asset:null,map:null,player:null,action:entity.kind==='fishSchool'?'rest':'idle',species:entity.kind==='hen'?'chicken':entity.kind==='cow'?'cow':entity.kind==='fishSchool'?'fish':'goat',reactionUntil:0,reactionAction:''};actors.set(key,actor);request(actor);}
 return{
  /** @param {readonly Readonly<import('./unified-world-model.js').WorldEntity>[]} entities */
  snapshot(entities){worldEntities=entities;},
  /** @param {import('three').Group} group @param {Readonly<import('./unified-world-model.js').WorldEntity>} entity */
  bind(group,entity){if(disposed)return;if(entity.kind==='fishSchool'){const members=fishSchoolMembers(entity),keys=new Set(members.map(m=>entity.id+'.member.'+m.slot));for(const[key,actor]of actors)if(actor.entity.id===entity.id&&!keys.has(key)){actor.sprite.removeFromParent();actor.map?.dispose();actor.sprite.material.dispose();actors.delete(key);}for(const member of members)bindOne(group,entity,entity.id+'.member.'+member.slot,member);if(!members.length)group.clear();}else if(['hen','goat','cow'].includes(entity.kind))bindOne(group,entity,entity.id,{x:0,z:0});},
  /** @param {readonly import('./engine.js').DomainEvent[]} events */
  events(events){for(const event of events){const id=milkedCow(event),actor=id?actors.get(id):null;if(actor?.entity.lactating){actor.reactionUntil=performance.now()+6500;actor.reactionAction='milk';}}},
  resetEffects(){resetPending=true;for(const actor of actors.values()){actor.reactionUntil=0;actor.reactionAction='';}},
  finishSnapshot(){resetPending=false;},
  /** @param {Set<string>} ids */
  retain(ids){for(const[id,actor]of actors)if(!ids.has(actor.entity.id)){actor.sprite.removeFromParent();actor.map?.dispose();actor.sprite.material.dispose();actors.delete(id);}},
  /** @param {boolean} next */
  setLow(next){if(low===next||disposed)return;low=next;for(const actor of actors.values())request(actor);},
  /** Keep the working Canvas until every already-owned oversized atlas has a usable GPU LOD. @param {number} limit */
  async constrain(limit){if(!Number.isFinite(limit)||limit<1)throw Error('Invalid texture capability');textureLimit=limit;await Promise.all([...actors.values()].filter(actor=>wanted(actor)==='low'&&actor.asset?.meta.lod!=='low').map(async actor=>{const asset=await load(actor.species,'low');if(asset.meta.width>limit||asset.meta.height>limit)throw Error('No fitting atlas LOD');if(wanted(actor)==='low')install(actor,asset);}));if(!disposed)options.changed();},
  /** @param {number} now @param {number} heading @param {boolean} still */
  update(now,heading,still){if(disposed)return 0;lastTime=now;let count=0;for(const actor of actors.values()){if(!actor.asset||!actor.player||!actor.map)continue;const desired=actor.reactionUntil>now?actor.reactionAction:actor.species==='chicken'?chickenPose(actor.entity,now):actor.species==='cow'?cowPose(actor.entity):actor.species==='fish'?fishPose(actor.entity):goatPose(actor.entity);if(actor.species!=='fish')actor.motion.moveTo(animalGoal(actor.entity,desired,worldEntities,now),now,worldEntities,WORLD_ART.species[actor.species].contactRadius,still);const movement=actor.motion.sample(now,still),action=actor.species!=='fish'&&movement.moving&&!still?'walk':desired;if(action!==actor.action){actor.action=action;actor.player.setAction(action,now);}actor.sprite.scale.setScalar(actor.asset.meta.worldUnits*(actor.entity.scale||1));actor.sprite.userData.stage=actor.entity.stage||'adult';const sample=actor.player.sample(now,{heading,actorHeading:actor.species==='fish'?stableArtHash(actor.key)%4:movement.heading,still}),pose=sample.pose,m=actor.asset.meta;actor.map.offset.set(pose.x/m.width,1-(pose.y+pose.height)/m.height);actor.map.repeat.set(pose.width/m.width,pose.height/m.height);updateAtlasFade(actor.sprite,sample,m);actor.sprite.userData.atlas={asset:actor.asset,pose,from:sample.from,mix:sample.mix};actor.sprite.userData.moving=actor.species!=='fish'&&movement.moving&&!still;actor.sprite.userData.acceptedCue=actor.reactionUntil>now?actor.reactionAction:'';actor.sprite.userData.action=action;actor.sprite.userData.direction=pose.direction;actor.sprite.userData.frame=pose.frame;const phase=now/700+stableArtHash(actor.key)%31,moving=!still&&(action==='walk'||action==='swim'||action==='feed');if(actor.species==='fish')actor.sprite.position.set(actor.offset.x+(moving?Math.sin(phase)*.1:0),actor.entity.groundY||0,actor.offset.z+(moving?Math.cos(phase)*.1:0));else actor.sprite.position.set(movement.x-actor.entity.x,movement.y,movement.z-actor.entity.z);count++;}return still?0:count;},
  inspect:()=>({actors:actors.size,ready:[...actors.values()].filter(a=>a.asset).length,byKind:Object.fromEntries(['hen','goat','cow','fishSchool'].map(kind=>[kind,{total:[...actors.values()].filter(a=>a.entity.kind===kind).length,ready:[...actors.values()].filter(a=>a.entity.kind===kind&&a.asset).length}])),assets:assets.size,errors,low,textureLimit,lastTime,actions:[...actors.values()].map(a=>({id:a.entity.id,action:a.action,ready:!!a.asset}))}),
  dispose(){if(disposed)return;disposed=true;for(const actor of actors.values()){actor.sprite.removeFromParent();actor.map?.dispose();actor.sprite.material.dispose();}actors.clear();for(const asset of assets){asset.texture.dispose();asset.image.src='';}assets.clear();cache.clear();}
 };
}
